param([string]$ProjectRoot=(Join-Path $PSScriptRoot '..'),[string]$BuildRoot='')
$ErrorActionPreference='Stop';$ProjectRoot=[IO.Path]::GetFullPath($ProjectRoot);if(!$BuildRoot){$BuildRoot=Join-Path $ProjectRoot 'out/build'};$BuildRoot=[IO.Path]::GetFullPath($BuildRoot)
Add-Type -Path (Join-Path $PSScriptRoot 'NativeChatTest.cs')
Add-Type -AssemblyName System.Drawing
$checks=0;$service=$null;$provider=$null
function Check($Condition,$Name){if(!$Condition){throw "CHECK FAILED: $Name"};$script:checks++;Write-Output "PASS $Name"}
function Wait-For([scriptblock]$Probe,$Name,[int]$Seconds=20){$end=[DateTime]::UtcNow.AddSeconds($Seconds);while([DateTime]::UtcNow-lt$end){if(& $Probe){return};Start-Sleep -Milliseconds 40};try{Api '/api/capabilities'|ConvertTo-Json -Depth 40|Set-Content "$root/timeout.json"}catch{};throw "TIMEOUT $Name"}
function Api($Path,$Data=$null){$a=@{Uri=$script:origin+$Path;Headers=@{Authorization='Bearer world-fixture-session'};TimeoutSec=10};if($null-ne$Data){$a.Method='Post';$a.ContentType='application/json';$a.Body=[Text.Encoding]::UTF8.GetBytes(($Data|ConvertTo-Json -Depth 35 -Compress))};Invoke-RestMethod @a}
function World{(Api '/api/capabilities').plugins.Where({$_.id-eq'habitat'})[0].current}
function Widget{(Api '/api/capabilities').plugins.Where({$_.id-eq'widget'})[0].current}
function Plugin($Name,$Arguments){$null=Api '/api/plugin/test' @{tool=$Name;args=$Arguments};Wait-For {$script:pluginResult=Api '/api/plugin/result';$script:pluginResult.state-in@('succeeded','failed','paused')} $Name;return $script:pluginResult.result}
function Plan($Responses){@{nonce=[Guid]::NewGuid().ToString('N');responses=@($Responses|ForEach-Object {@{response=$_}})}|ConvertTo-Json -Depth 40|Set-Content "$root/provider/plan.json" -Encoding utf8}
function Reply($Text){@{version=1;kind='reply';text=$Text;calls=@()}}
function Tool($Id,$Name,$Arguments){@{id=$Id;tool=$Name;args=$Arguments}}
function Calls($Items){@{version=1;kind='call';text=$null;calls=@($Items)}}
function Message($Text){$null=Api '/api/message' @{request_id=[Guid]::NewGuid().ToString('N');text=$Text};Wait-For {!(Api '/api/chat').busy} 'model turn'}
function Feedback{$capture=Get-Content "$root/provider/last-request.json" -Raw|ConvertFrom-Json -Depth 60;($capture.messages[-1].content|ConvertFrom-Json -Depth 50).tool_results}
function Start-Backend{
 Remove-Item "$root/ready.json" -ErrorAction SilentlyContinue
 $script:service=Start-Process "$BuildRoot/hibernation-agent.exe" -ArgumentList ('--desktop --config "'+$root+'/config.json" --ready-file "'+$root+'/ready.json"') -WindowStyle Hidden -PassThru -RedirectStandardOutput "$root/service.log" -RedirectStandardError "$root/error.log"
 Wait-For {if($service.HasExited){throw 'desktop exited'};Test-Path "$root/ready.json"} 'desktop';$script:origin='http://127.0.0.1:'+((Get-Content "$root/ready.json" -Raw|ConvertFrom-Json).port)
 $script:widget=[ChatWindowTest]::Find($service.Id,'HibernationDinosaurOverlay');$main=[ChatWindowTest]::Find($service.Id,'HibernationConversationV2');$null=[ChatWindowTest]::Send($main,0x10)
}
function Stop-Backend{$null=Api '/api/shutdown' @{};Check ($service.WaitForExit(10000)-and$service.ExitCode-eq0) 'world shuts down cleanly'}
$root=Join-Path $ProjectRoot ('artifacts/desk-world-'+[Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force $root|Out-Null
$env:HIBERNATION_SESSION_KEY='world-fixture-session';$env:HIBERNATION_WORLD_KEY='synthetic-world-model';$env:TEMP="$BuildRoot/tmp";$env:TMP=$env:TEMP
try{
 $provider=Start-Process "$BuildRoot/Hibernation_TestProvider.exe" -ArgumentList ('"'+$root+'/provider"') -WindowStyle Hidden -PassThru -RedirectStandardOutput "$root/provider.log" -RedirectStandardError "$root/provider-error.log";Wait-For {Test-Path "$root/provider/port"} 'provider';$fixture='http://127.0.0.1:'+(Get-Content "$root/provider/port")
 $cfg=Get-Content "$ProjectRoot/config/example.json" -Raw|ConvertFrom-Json -AsHashtable;$cfg.dataRoot="$root/data";$cfg.characterRoot="$ProjectRoot/character";$cfg.uiRoot="$ProjectRoot/ui";$cfg.pluginRoot="$BuildRoot/plugins";$cfg.solitudeIntervalMs=600000;$cfg.idleBeforeSolitudeMs=600000;$cfg.maxStartsPerHour=1000;$cfg.plugins=@{widget=@{enabled=$true;roam=$false};habitat=@{enabled=$true;autoSpawn=$false;autoInteract=$false;wakeOnAction=$false;maxObjects=3}}
 $cfg.profiles+=@{id='fixture';label='World fixture';enabled=$true;protocol='chat-completions';origin=$fixture;basePath='/v1';model='fixture-model';credentialEnvironment='HIBERNATION_WORLD_KEY';timeoutMs=10000;maxOutputTokens=2048};$cfg|ConvertTo-Json -Depth 40|Set-Content "$root/config.json" -Encoding utf8
 Start-Backend;$null=Api '/api/model' @{id='fixture'};Wait-For {(World).desktop-and(Widget).visible} 'world ready';Check ([ChatWindowTest]::Find($service.Id,'HibernationDeskObjects')-ne[IntPtr]::Zero) 'world window belongs to isolated desktop process'
 Check (@((Api '/api/capabilities').tools|Where-Object {$_.tool-like'habitat.*'}).Count-eq4) 'all world abilities are discoverable without user hints'
 $placed=Plugin 'habitat.place' @{kind='berry'};Check ($placed.ok-and$placed.result.objects.Count-eq1) 'placing creates a real bounded virtual object';$food=$placed.result.objects[0]
 $accepted=Plugin 'habitat.act' @{id=$food.id;action='eat'};Check ($accepted.ok-and$accepted.result.accepted-and!$accepted.result.completed-and(World).objects.Count-eq1) 'accepted action is not claimed as completed eating'
 Wait-For {(World).objects.Count-eq0-and(World).last_actions.Count-eq1} 'actual walk and eating' 25;Check ((World).last_actions[-1].kind-eq'habitat.consumed') 'only actual arrival and completion consume food'
 $ate=World;Start-Sleep -Milliseconds 500;Check ((World).last_actions.Count-eq1) 'one food creates one completed experience'
 Wait-For {(Api '/api/events' @{channel='agent.world.habitat'}).events.Count-eq1} 'world virtual event channel';$worldEvents=Api '/api/events' @{channel='agent.world.habitat'};Check ($worldEvents.events[0].channel-eq'agent.world.habitat.consumed') 'world uses the existing engine virtual channel';Check (!(($worldEvents|ConvertTo-Json -Depth 20).Contains('浆果'))-and!(($worldEvents|ConvertTo-Json -Depth 20).Contains('"text"'))) 'world event index contains no experience body'
 Plan @((Calls @((Tool 'observe' 'habitat.observe' @{}))),(Calls @((Tool 'remember' 'memory.remember' @{kind='outer';text='桌面上真实吃到一颗虚拟浆果。';source_ids=@('${last_source_id}')}))),(Reply '刚才那一颗已经吃到了。'));Message '刚才发生了什么';Check ((Feedback)[0].ok) 'completed world observation can become a sourced outer memory'
 $capture=Get-Content "$root/provider/last-request.json" -Raw|ConvertFrom-Json -Depth 60;$context=$capture.messages[1].content|ConvertFrom-Json -Depth 50;Check (@($context.authorized_context|Where-Object {$_.data.text-like'*实际*'-or$_.data.plugin_event_id}).Count-gt0) 'actual world experience is available in later conversation context'
 $placed=Plugin 'habitat.place' @{kind='berry'};$second=$placed.result.objects[0]
 Plan @((Calls @((Tool 'start' 'habitat.act' @{id=$second.id;action='eat'}))),(Calls @((Tool 'false-memory' 'memory.remember' @{kind='outer';text='尚未吃到却声称吃完。';source_ids=@('${last_source_id}')}))),(Reply '只是准备过去，还没有吃到。'));Message '提前记忆校验';$feedback=Feedback;Check (!$feedback[0].ok-and$feedback[0].error.code-eq'memory_category_requires_experience') 'accepted intent alone cannot authenticate an already completed experience'
 Plan @((Reply '先听你这句话。'));Message '先停下刚才的动作';Start-Sleep -Milliseconds 700;Check ((World).objects.Count-eq1-and$null-eq(World).pending-and(World).last_actions.Count-eq1) 'new conversation cancels an old world action without eating later'
 $seed=Plugin 'habitat.place' @{kind='seed'};$seedItem=@($seed.result.objects|Where-Object kind -eq seed)[0];$plant=Plugin 'habitat.act' @{id=$seedItem.id;action='plant'};Check $plant.ok 'seed accepts a planting intention'
 Wait-For {@((World).objects|Where-Object kind -eq sprout).Count-eq1} 'actual seed planting' 25;$saved=(World).objects|ConvertTo-Json -Depth 15 -Compress;Stop-Backend;Start-Backend;Wait-For {(World).objects.Count-eq2} 'world restore';Check (((World).objects|ConvertTo-Json -Depth 15 -Compress)-eq$saved-and$null-eq(World).pending) 'restart preserves objects and plant growth without replaying old actions'
 $null=Plugin 'habitat.show' @{visible=$false};Wait-For {![ChatWindowTest]::IsWindowVisible([ChatWindowTest]::Find($service.Id,'HibernationDeskObjects'))} 'hide objects';$hiddenClock=(World).clock;Start-Sleep -Milliseconds 300;Check ((World).clock-gt$hiddenClock) 'hidden objects continue their background life';$null=Api '/api/surfaces/show' @{id='habitat'};Wait-For {[ChatWindowTest]::IsWindowVisible([ChatWindowTest]::Find($service.Id,'HibernationDeskObjects'))} 'reopen objects';Check $true 'hidden desk objects have a reopening route'
 $settings=(Api '/api/dashboard').settings;$settings.plugins.widget.enabled=$false;$rejected=$false;try{$null=Api '/api/settings' @{settings=$settings}}catch{$rejected=$true};Check ($rejected-and(World).desktop-and(Widget).visible) 'missing widget dependency is rejected without losing loaded world'
 $null=[ChatWindowTest]::SetThreadDpiAwarenessContext([IntPtr](-4));$bounds=New-Object ChatWindowTest+Rect;$null=[ChatWindowTest]::GetClientRect($widget,[ref]$bounds);$image=New-Object Drawing.Bitmap($bounds.right,$bounds.bottom);$graphics=[Drawing.Graphics]::FromImage($image);$graphics.Clear([Drawing.Color]::FromArgb(247,248,243))
 try{foreach($class in @('HibernationDinosaurOverlay','HibernationDeskObjects')){$h=[ChatWindowTest]::Find($service.Id,$class);$layer=New-Object Drawing.Bitmap($bounds.right,$bounds.bottom);$g=[Drawing.Graphics]::FromImage($layer);try{$dc=$g.GetHdc();try{$null=[ChatWindowTest]::PrintWindow($h,$dc,1)}finally{$g.ReleaseHdc($dc)};$g.Dispose();$layer.MakeTransparent([Drawing.Color]::Magenta);$graphics.DrawImageUnscaled($layer,0,0)}finally{$g.Dispose();$layer.Dispose()}};$image.Save("$root/world-native.png")}finally{$graphics.Dispose();$image.Dispose()}
 Stop-Backend;@{completed=$true;checks=$checks;root=$root;timestamp=[DateTime]::UtcNow.ToString('O')}|ConvertTo-Json|Set-Content "$root/acceptance.json";Write-Output "Desk world passed: $checks checks. Evidence: $root"
}finally{if($service){$service.Refresh();if(!$service.HasExited){try{$null=Api '/api/shutdown' @{};$service.WaitForExit(5000)|Out-Null}catch{};$service.Refresh();if(!$service.HasExited){Stop-Process -Id $service.Id}}};if($provider){$provider.Refresh();if(!$provider.HasExited){Stop-Process -Id $provider.Id}}}
